#pragma once
// ==========================================================
//  fan_img.h - the ceiling fan tile, 200x200 RGB565
//
//  Made from the photograph of the actual fan in the room.
//  White blades on a white background, so they were cut out
//  by luminance rather than colour, then redrawn in soft
//  off-white on a dark slate-violet ground.
//
//    bed #4A3E2E amber   radio #2E4238 green
//    ac  #2C3C4A blue    fan   #221E2C violet, darkened
//
//  Byte order is LITTLE endian, low byte first, exactly as
//  tile_img.h stores its tiles. Get that backwards and the
//  colours come out wrong while the picture stays perfectly
//  recognisable - the hardest kind of mistake to spot.
// ==========================================================
#include <Arduino.h>
#include <lvgl.h>

